"""
Unit tests for the kpanic label pipeline.

Covers:
- _flags private attr on SuggestImpactModel
- label:kpanic in suggest_impact() updated_fields
- FlawUpdater label creation via _create_labels()
"""

from datetime import UTC, datetime
from types import SimpleNamespace
from unittest.mock import AsyncMock, MagicMock, patch

import pytest

from aegis_ai.features.cve.data_models import SuggestImpactModel
from aegis_ai.osidb_bot.bot import FlawUpdater

CVE_ID = "CVE-2025-99999"

_DISCLAIMER = (
    "This response was generated by Aegis AI "
    "(https://github.com/RedHatProductSecurity/aegis-ai) "
    "using generative AI for informational purposes. "
    "All findings should be validated by a human expert."
)


def _base_model_kwargs(**overrides):
    """Common kwargs required by AegisFeatureModel base class."""
    defaults = {
        "cve_id": CVE_ID,
        "title": "test",
        "explanation": "test",
        "impact": "LOW",
        "cvss3_score": "3.7",
        "cvss3_vector": "CVSS:3.1/AV:L/AC:L/PR:L/UI:N/S:U/C:N/I:N/A:L",
        "data_quality": 0.9,
        "confidence": 0.9,
        "tools_used": ["osidb_tool"],
        "disclaimer": _DISCLAIMER,
    }
    defaults.update(overrides)
    return defaults


class TestSuggestImpactModelFlags:
    """Verify the _flags private attr on SuggestImpactModel."""

    def test_flags_defaults_to_empty_list(self):
        model = SuggestImpactModel(**_base_model_kwargs())
        assert model._flags == []

    def test_flags_not_in_json_schema(self):
        schema = SuggestImpactModel.model_json_schema()
        assert "flags" not in schema.get("properties", {})
        assert "_flags" not in schema.get("properties", {})

    def test_flags_not_in_model_dump(self):
        model = SuggestImpactModel(**_base_model_kwargs())
        model._flags = ["kpanic"]
        dumped = model.model_dump()
        assert "flags" not in dumped
        assert "_flags" not in dumped

    def test_flags_settable_after_construction(self):
        model = SuggestImpactModel(**_base_model_kwargs())
        model._flags = ["kpanic"]
        assert model._flags == ["kpanic"]


def _minimal_flaw_data() -> dict:
    """Build minimal flaw_data that passes FlawFinder.validate()."""
    return {
        "aegis_meta": {},
        "affects": [],
        "classification": {"workflow": "DEFAULT", "state": "NEW"},
        "comment_zero": "",
        "comments": [],
        "components": [],
        "created_dt": "2025-01-01T00:00:00Z",
        "cve_description": "",
        "cve_id": CVE_ID,
        "cvss_scores": [],
        "cwe_id": "",
        "embargoed": False,
        "impact": "",
        "mitigation": "",
        "owner": "",
        "references": [],
        "source": "CVEORG",
        "statement": "",
        "title": "",
        "updated_dt": "2025-01-01T00:00:00Z",
        "uuid": "00000000-0000-0000-0000-000000000099",
    }


def _mock_session(flaw_data: dict) -> MagicMock:
    session = MagicMock()
    session.flaws.retrieve.return_value = MagicMock(to_dict=lambda: flaw_data)
    session.status.return_value = MagicMock(
        dt=datetime(2025, 6, 1, 12, 0, 0, tzinfo=UTC)
    )
    session.flaws.update = MagicMock()
    session.flaws.cvss_scores = MagicMock()
    session.flaws.cvss_scores.create = MagicMock()
    session.flaws.labels = MagicMock()
    session.flaws.labels.create = MagicMock()
    return session


async def _canned_exec_feature_with_flags(feature, flaw_data):
    """Fake exec_feature returning a SuggestImpact output with A:H in CVSS."""
    name = feature.__class__.__name__

    if name == "SuggestAffectedComponents":
        return SimpleNamespace(
            components=["kernel"],
            ecosystems=[],
            explanation="test",
            data_quality=0.9,
            confidence=0.9,
            tools_used=[],
        )
    if name == "SuggestDescriptionText":
        return SimpleNamespace(
            suggested_title="Test title",
            suggested_description="Test desc.",
            explanation="test",
            data_quality=0.9,
            confidence=0.9,
            tools_used=[],
        )
    if name == "SuggestCWE":
        return SimpleNamespace(
            cwe=["CWE-416"],
            explanation="test",
            data_quality=0.9,
            confidence=0.9,
            tools_used=[],
        )
    if name == "SuggestImpact":
        return SimpleNamespace(
            impact="IMPORTANT",
            cvss3_score="7.0",
            cvss3_vector="CVSS:3.1/AV:L/AC:H/PR:L/UI:N/S:U/C:N/I:N/A:H",
            explanation="Kernel panic detected",
            data_quality=0.9,
            confidence=0.9,
            tools_used=[],
        )
    if name == "SuggestStatementText":
        return SimpleNamespace(
            suggested_statement="Test statement.",
            suggested_mitigation="Test mitigation.",
            explanation="test",
            data_quality=0.9,
            confidence=0.9,
            tools_used=[],
        )
    if name == "SuggestManifestComponentAndState":
        return SimpleNamespace(
            manifest_components=[],
            explanation="No downstream names for a kernel component are suggested here.",
            data_quality=0.9,
            confidence=0.9,
            tools_used=["osidb_tool"],
        )
    raise ValueError(f"Unknown feature: {name}")


@pytest.mark.asyncio
class TestSuggestImpactKpanicLabel:
    """Test that suggest_impact() adds label:kpanic to changed fields."""

    @patch("aegis_ai.osidb_bot.suggest.exec_feature", new_callable=AsyncMock)
    async def test_kpanic_label_for_kernel_with_ah(self, mock_exec):
        mock_exec.side_effect = _canned_exec_feature_with_flags

        flaw_data = _minimal_flaw_data()
        flaw_data["components"] = ["kernel"]
        from aegis_ai.osidb_bot.suggest import suggest_impact

        ts = datetime(2025, 6, 1, 12, 0, 0, tzinfo=UTC)
        agent = MagicMock()
        changed = await suggest_impact(agent, flaw_data, ts)

        assert "label:kpanic" in changed

    @patch("aegis_ai.osidb_bot.suggest.exec_feature", new_callable=AsyncMock)
    async def test_no_kpanic_label_without_ah_in_cvss(self, mock_exec):
        """No label:kpanic when CVSS vector lacks A:H."""

        async def _no_ah(feature, flaw_data):
            name = feature.__class__.__name__
            if name == "SuggestImpact":
                return SimpleNamespace(
                    impact="MODERATE",
                    cvss3_score="5.5",
                    cvss3_vector="CVSS:3.1/AV:L/AC:L/PR:L/UI:N/S:U/C:N/I:N/A:L",
                    explanation="test",
                    data_quality=0.9,
                    confidence=0.9,
                    tools_used=[],
                )
            return await _canned_exec_feature_with_flags(feature, flaw_data)

        mock_exec.side_effect = _no_ah

        flaw_data = _minimal_flaw_data()
        flaw_data["components"] = ["kernel"]
        from aegis_ai.osidb_bot.suggest import suggest_impact

        ts = datetime(2025, 6, 1, 12, 0, 0, tzinfo=UTC)
        changed = await suggest_impact(MagicMock(), flaw_data, ts)

        assert "label:kpanic" not in changed


@pytest.mark.asyncio
class TestFlawUpdaterLabelCreation:
    """Test that FlawUpdater.do() creates alias labels for label:kpanic."""

    @patch("aegis_ai.osidb_bot.suggest.exec_feature", new_callable=AsyncMock)
    async def test_labels_created_for_kpanic(self, mock_exec):
        mock_exec.side_effect = _canned_exec_feature_with_flags

        flaw_data = _minimal_flaw_data()
        session = _mock_session(flaw_data)
        agent = MagicMock()

        updater = FlawUpdater(session, agent, CVE_ID)
        await updater.do()

        # Verify labels.create was called with kpanic
        session.flaws.labels.create.assert_called_once_with(
            flaw_id="00000000-0000-0000-0000-000000000099",
            form_data={
                "name": "kpanic",
                "type": "alias",
                "state": "NEW",
            },
        )

    @patch("aegis_ai.osidb_bot.suggest.exec_feature", new_callable=AsyncMock)
    async def test_label_creation_failure_does_not_crash(self, mock_exec):
        """A failed label creation is logged but doesn't abort the update."""
        mock_exec.side_effect = _canned_exec_feature_with_flags

        flaw_data = _minimal_flaw_data()
        session = _mock_session(flaw_data)
        session.flaws.labels.create.side_effect = RuntimeError("OSIDB 500")
        agent = MagicMock()

        updater = FlawUpdater(session, agent, CVE_ID)
        await updater.do()

        # The flaw update itself should still have succeeded
        session.flaws.update.assert_called_once()
        # label:kpanic should be removed from updated_fields on failure
        assert "label:kpanic" not in updater.updated_fields
